#include "core/integration.hpp"
#include "core/terminal.hpp"
#include "core/personalization.hpp"
#include <set>
#include <algorithm>
#include <iostream>
int main(){using namespace aether;int count=0;auto check=[&](bool value,const char* name){if(!value){std::cerr<<"FAIL "<<name<<'\n';std::exit(1);}++count;};IntegrationOptions options;check(!options.windowsMode&&!options.windowsAccent&&!options.frames&&!options.terminal&&options.restoreOnExit,"external integration is opt-in");options.terminal=true;options.terminalFont="Consolas";options.terminalSize=19;options.terminalBackground=true;options.rules={{"explorer.exe",FrameMode::Dark},{"example.exe",FrameMode::Leave}};check(parseIntegration(serializeIntegration(options))==options,"integration settings roundtrip");auto invalid=parseIntegration("AetherIntegration1\nsize 900\nopacity -5\nrule \"../bad.exe\" 1\nrule \"APP.EXE\" 2\nrule \"app.exe\" 3\n");check(invalid.terminalSize==24&&invalid.terminalOpacity==50&&invalid.rules.size()==1&&invalid.rules[0].executable=="app.exe","bounded settings and normalized exact executable rules");check(!parseIntegration("invalid\nwindowsMode 1").windowsMode,"invalid schema cannot enable Windows changes");check(darkTheme(preset(1))&&!darkTheme(preset(2)),"luminance controls dark mode");check(terminalPalette(preset(2))[15]==0x181C24,"light terminal palette keeps bright ANSI text legible");auto json=terminalFragment(preset(1),options,"C:\\Windows","C:\\art\\green.png");check(json.find("Aether PowerShell")!=json.npos&&json.find("Aether Command Prompt")!=json.npos&&json.find("Aether WSL")!=json.npos,"three explicit Terminal profiles");check(json.find("defaultProfile")==json.npos&&json.find("backgroundImageOpacity")!=json.npos,"fragment does not replace user defaults");check(jsonString("a\"b\\c\n")=="\"a\\\"b\\\\c\\u000a\"","JSON escapes untrusted strings");
 TerminalGrid grid;grid.resize(20,5);grid.feed("hello\r\nworld");check(grid.cells()[0].glyph==U'h'&&grid.cells()[20].glyph==U'w',"terminal carriage return and newline");grid.feed("\x1b[2;3HX");check(grid.cells()[22].glyph==U'X',"terminal cursor addressing");grid.feed("\x1b[38;2;1;2;3mZ");check(grid.cells()[23].foreground==0x010203,"terminal truecolor");grid.feed("\x1b[0m\x1b[3;1H\xE2\x82");grid.feed("\xAC");check(grid.cells()[40].glyph==U'€',"fragmented UTF-8 survives reads");auto before=grid.cells();grid.feed("\x1b[?1049hALT\x1b[?1049l");check(grid.cells()==before,"alternate-screen restoration");grid.feed("\x1b[?2004h\x1b[?25l");check(grid.bracketedPaste&&!grid.cursorVisible,"paste and cursor modes");grid.feed("\x1b[6n");check(grid.takeResponse().ends_with("R"),"terminal cursor query response");grid.feed("\x1b]52;c;MALICIOUS_CLIPBOARD\x07");check(grid.cells()==before,"OSC does not execute clipboard or host commands");for(int n=0;n<2100;++n)grid.feed("line\r\n");check(grid.history().size()==2000,"scrollback is bounded");grid.resize(10000,10000);check(grid.columns()==512&&grid.rows()==200&&grid.cells().size()==102400,"terminal dimensions are bounded");TerminalGrid malformed;malformed.feed("\x1b["+std::string(20000,'1')+"m");check(malformed.cells().size()==80*24,"hostile escape streams remain bounded");TerminalGrid inverse;inverse.feed("\x1b[7mA\x1b[7mB\x1b[27mC");check(inverse.cells()[0].foreground==inverse.cells()[1].foreground&&inverse.cells()[0].foreground!=inverse.cells()[2].foreground,"inverse mode is idempotent and resets");TerminalGrid alternate;alternate.feed("original\x1b[?1049halt");alternate.resize(100,30);alternate.feed("\x1b[?1049l");check(alternate.cells()[0].glyph==U'o',"normal screen survives resizing in alternate mode");TerminalGrid queries;for(int n=0;n<20000;++n)queries.feed("\x1b[6n");check(queries.takeResponse().size()<65536,"terminal response queue is bounded");std::set<std::uint32_t> stock;
 for(int n=1;n<=10;++n){auto t=terminalDesignTheme(preset(1),n);stock.insert(t.background);check(contrastRatio(t.background,t.foreground)>=7.0,"stock text has strong contrast");options.terminalDesign=n;options.terminalCursor=n%3;options.terminalShell=n%3;options.terminalImage="C:\\Pictures\\calm pond.png";check(parseIntegration(serializeIntegration(options))==options,"each stock design and local customization roundtrips");}
 check(stock.size()==10,"ten distinct stock designs");check(!validTerminalImage("https://example.com/picture.png")&&!validTerminalImage("C:relative.png")&&!validTerminalImage("C:\\bad.exe"),"background paths exclude commands and remote URLs");check(terminalDesignTheme(preset(1),99)==preset(1),"unknown design follows desktop safely");
 TerminalGrid mode;mode.feed("\x1b[?1h");check(mode.applicationCursor,"application cursor mode enabled");mode.feed("\x1b[?1l");check(!mode.applicationCursor,"application cursor mode disabled");mode.feed("\x1bPdiscard me\x1b\\OK");check(mode.cells()[0].glyph==U'O',"DCS payload is not printed or executed");
 std::cout<<count<<" integration/VT core checks passed\n";}
